#!/usr/bin/env bash
# Launcher for the Airlock control console.
#
# The console is a local-only web app (127.0.0.1 + one-time token), generated by
# the server itself -- there is no static HTML file to open. This script is the
# entry point.
#
# Usage: ./airlock-ui.sh [--app web] [--port 7788] [--token ...] [--no-open]
set -euo pipefail
cd "$(dirname "$0")"

if ! command -v node >/dev/null 2>&1; then
    echo "Node.js was not found on PATH. Airlock needs Node.js 24 or newer: https://nodejs.org/" >&2
    exit 1
fi

exec node bin/airlock-deploy-ui.mjs "$@"